import React, { useState, useRef, useEffect } from 'react';
import { 
  Trash2, Map, Calendar, Star, LineChart, Users, 
  HardHat, FileText, Activity, Search, Filter, 
  ShieldAlert, AlertCircle, ChevronRight, ChevronLeft
} from 'lucide-react';

const Dashboard = () => {
  const [activeTab, setActiveTab] = useState('BINS');
  const scrollRef = useRef(null);

  const allTabs = [
    { id: 'BINS', label: '01_BIN_MONITORING', icon: <Trash2 size={20}/> },
    { id: 'ZONES', label: '02_AREAS_&_ZONES', icon: <Map size={20}/> },
    { id: 'SCHEDULE', label: '03_COLL_SCHEDULE', icon: <Calendar size={20}/> },
    { id: 'POINTS', label: '04_REWARDS_POINTS', icon: <Star size={20}/> },
    { id: 'ANALYTICS', label: '05_SYS_ANALYTICS', icon: <LineChart size={20}/> },
    { id: 'CITIZENS', label: '06_CITIZEN_INFO', icon: <Users size={20}/> },
    { id: 'WORKERS', label: '07_WORKER_NODES', icon: <HardHat size={20}/> },
    { id: 'REPORTS', label: '08_SYS_REPORTS', icon: <FileText size={20}/> },
  ];

  // Function to handle clicking a tab and sliding the "Machine"
  const scrollToTab = (tabId, index) => {
    setActiveTab(tabId);
    if (scrollRef.current) {
      const width = scrollRef.current.offsetWidth;
      scrollRef.current.scrollTo({
        left: width * index,
        behavior: 'smooth'
      });
    }
  };

  return (
    <div className="w-full max-w-[1600px] h-[95vh] flex flex-col gap-4 p-4 md:p-6 animate-slot">

      {/* BLOCK 1: HEADER */}
      <div className="bg-[#AB1717] border-[6px] border-[#47510B] rounded-t-[40px] rounded-b-[12px] p-5 red-stack-shadow shrink-0">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="bg-[#FDFAD8] p-2 rounded-xl border-4 border-[#47510B] shadow-[3px_3px_0_0_#47510B]">
              <ShieldAlert size={28} className="text-[#AB1717]" strokeWidth={2.5} />
            </div>
            <h1 className="text-2xl md:text-3xl font-black italic tracking-tighter text-[#FDFAD8] uppercase">
              TRASH<span className="text-[#CAD23C]">2</span>TRACK
            </h1>
          </div>
          <Activity className="text-[#CAD23C] animate-pulse" size={24} />
        </div>
      </div>

      {/* BLOCK 2: THE SELECTOR TRAY (THE "CONTROL BUTTONS") */}
      <div className="bg-[#A1AED1] border-[6px] border-[#47510B] rounded-[20px] p-3 yellow-stack-shadow shrink-0">
        <div className="flex flex-wrap gap-2 justify-center lg:justify-start">
          {allTabs.map((tab, index) => (
            <button
              key={tab.id}
              onClick={() => scrollToTab(tab.id, index)}
              className={`
                flex items-center gap-2 px-4 py-3 rounded-[15px] border-[3px] border-[#47510B] font-black text-[10px] uppercase transition-all
                ${activeTab === tab.id 
                  ? 'bg-[#CAD23C] text-[#47510B] translate-y-1 shadow-none' 
                  : 'bg-[#FDFAD8] text-[#AB1717] shadow-[3px_3px_0_0_#47510B] hover:translate-y-0.5'}
              `}
            >
              {tab.icon}
              <span className="hidden lg:inline">{tab.label}</span>
            </button>
          ))}
        </div>
      </div>

      {/* BLOCK 3: THE SWIPEABLE CONSOLE SCREEN */}
      <div className="bg-[#AB1717] border-[6px] border-[#47510B] rounded-t-[12px] rounded-b-[40px] p-2 md:p-4 red-stack-shadow flex-grow flex flex-col min-h-0 relative">

        {/* Horizontal Scroll Container */}
        <div 
          ref={scrollRef}
          className="flex-grow w-full flex overflow-x-auto snap-x snap-mandatory no-scrollbar scroll-smooth rounded-[25px]"
          style={{ scrollbarWidth: 'none' }}
        >
          {allTabs.map((tab, index) => (
            <div 
              key={tab.id} 
              className="min-w-full h-full snap-start px-2 py-2"
            >
              <div className="bg-[#FDFAD8] w-full h-full rounded-[25px] border-[5px] border-[#47510B] p-6 shadow-inner flex flex-col overflow-hidden">

                {/* Module Header */}
                <div className="flex justify-between items-center border-b-4 border-[#47510B]/10 pb-4 mb-6 shrink-0">
                  <h2 className="text-xl md:text-2xl font-black italic uppercase tracking-tighter text-[#47510B]">
                    {tab.label.replace(/_/g, ' ')} <span className="text-[#AB1717]">_ACTIVE</span>
                  </h2>
                  <div className="flex gap-2">
                     <div className="text-[10px] font-black opacity-30 uppercase tracking-[0.4em]">MODULE_0{index + 1}</div>
                  </div>
                </div>

                {/* Data Area (Scrollable within each tab) */}
                <div className="flex-grow overflow-y-auto pr-2 custom-scrollbar text-[#47510B]">
                   {tab.id === 'BINS' && <BinModule />}
                   {tab.id === 'CITIZENS' && <CitizenModule />}
                   {/* Fallback for other modules */}
                   {!['BINS', 'CITIZENS'].includes(tab.id) && (
                      <div className="h-full flex flex-col items-center justify-center opacity-20 py-20">
                         <AlertCircle size={64} className="mb-4" />
                         <p className="font-black text-xl uppercase italic tracking-widest text-center">Data_Packet_Pending <br/> Sector_{index + 1}</p>
                      </div>
                   )}
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Swipe Indicators (Floating) */}
        <div className="absolute left-6 top-1/2 -translate-y-1/2 pointer-events-none opacity-20">
          <ChevronLeft size={48} className="text-[#FDFAD8]" />
        </div>
        <div className="absolute right-6 top-1/2 -translate-y-1/2 pointer-events-none opacity-20">
          <ChevronRight size={48} className="text-[#FDFAD8]" />
        </div>

      </div>
    </div>
  );
};

// ... Keep your BinModule and CitizenModule from the previous step ...
